require_once __DIR__.'/includes/email.php';email_require('view');if(!Auth::isAdmin()&&!Auth::can('email_hub.rules','edit')){http_response_code(403);exit('دسترسی غیرمجاز است.');}$pageTitle='قوانین خودکار ایمیل';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/email-rules.php');}try{$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));if($title==='')throw new InvalidArgumentException('عنوان قانون الزامی است.');$fields=['from','subject','body','has_attachment','age_hours'];$operators=['contains','equals','domain','greater_than'];$actions=['add_tag','assign_user','assign_group','create_ticket','set_pending_reply','mark_important'];$data=[$title,(int)($_POST['account_id']??0)?:null,in_array($_POST['condition_field']??'',$fields,true)?$_POST['condition_field']:'subject',in_array($_POST['condition_operator']??'',$operators,true)?$_POST['condition_operator']:'contains',trim((string)($_POST['condition_value']??'')),in_array($_POST['action_type']??'',$actions,true)?$_POST['action_type']:'add_tag',trim((string)($_POST['action_value']??'')),max(1,(int)($_POST['priority']??100)),isset($_POST['active'])?1:0];if($id)Database::execute('UPDATE email_rules SET title=?,account_id=?,condition_field=?,condition_operator=?,condition_value=?,action_type=?,action_value=?,priority=?,active=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else Database::execute('INSERT INTO email_rules(title,account_id,condition_field,condition_operator,condition_value,action_type,action_value,priority,active,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,NOW(),NOW())',[...$data,(int)Auth::user()['id']]);flash('قانون خودکار ذخیره شد.');}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){flash(email_safe_error($e,'ذخیره قانون انجام نشد.'),'danger');}redirect('/admin/email-rules.php');}
