<section class="card email-form-card"><h2><?=$edit?'ویرایش قانون':'قانون جدید'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="grid grid-3"><label class="form-field"><span>عنوان</span><input name="title" required value="<?=e($edit['title']??'')?>"></label><label class="form-field"><span>حساب</span><select name="account_id"><option value="">همه حساب‌ها</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" <?=(int)($edit['account_id']??0)===(int)$a['id']?'selected':''?>><?=e($a['account_title'])?></option><?php endforeach?></select></label><label class="form-field"><span>فیلد شرط</span><select name="condition_field"><?php foreach($fieldLabels as $v=>$l):?><option value="<?=$v?>" <?=($edit['condition_field']??'subject')===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></label><label class="form-field"><span>عملگر</span><select name="condition_operator"><?php foreach($operatorLabels as $v=>$l):?><option value="<?=$v?>" <?=($edit['condition_operator']??'contains')===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></label><label class="form-field"><span>مقدار شرط</span><input name="condition_value" value="<?=e($edit['condition_value']??'')?>"></label><label class="form-field"><span>عملیات</span><select name="action_type"><?php foreach($actionLabels as $v=>$l):?><option value="<?=$v?>" <?=($edit['action_type']??'add_tag')===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></label><label class="form-field"><span>مقدار عملیات</span><input name="action_value" value="<?=e($edit['action_value']??'')?>" placeholder="برچسب، شناسه کاربر یا نام گروه"></label><label class="form-field"><span>اولویت اجرا</span><input type="number" min="1" name="priority" value="<?=e($edit['priority']??'100')?>"></label><label class="checkbox-item"><input type="checkbox" name="active" <?=!isset($edit['active'])||(int)$edit['active']?'checked':''?>> فعال</label></div><button class="btn btn-primary">ذخیره قانون</button></form></section><section class="card"><div class="table-wrap"><table><thead><tr><th>قانون</th><th>حساب</th><th>شرط</th><th>عملیات</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['title'])?></td><td><?=e($i['account_title']?:'همه')?></td><td><?=e(($fieldLabels[$i['condition_field']]??'شرط').' / '.($operatorLabels[$i['condition_operator']]??'عملگر').' / '.$i['condition_value'])?></td><td><?=e(($actionLabels[$i['action_type']]??'عملیات').($i['action_value']!==''?' / '.$i['action_value']:''))?></td><td><?=$i['active']?'فعال':'غیرفعال'?></td><td><a class="btn btn-small" href="?edit=<?=$i['id']?>">ویرایش</a></td></tr><?php endforeach?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
